2xRvRAixuocjCm40.command:
//init vars
let macroTarget = game.settings.get('mosh','macroTarget');
//warn user if character is not selected
if ((macroTarget === 'character' && !game.user.character) || (macroTarget === 'token' && !canvas.tokens.controlled.length)) {
  //warn player
  game.mosh.noCharSelected();
//else pop up the dialog
} else {
  //pop up the death save dialog box
  new new foundry.applications.api.DialogV2({
    window: {
      title: "Death Save"
    },
    classes: ["macro-popup-dialog"],
    position: {width: 600},
    content: `
      <div class ="macro_window" style="margin-bottom : 7px;">
        <div class="grid grid-2col" style="grid-template-columns: 150px auto">
          <div class="macro_img"><img src="systems/mosh/images/icons/ui/rolltables/death_save.png" style="border:none"/></div>
          <div class="macro_desc">
            <h4>Death Save</h4>
            <strong>Cada vez que tu Salud llegue a 0, haz una Salvación de Cuerpo: si fallas, mueres.</strong> Si tienes éxito, caes inconsciente; haz una <strong>Salvación de Muerte</strong> para averiguar cuándo recuperas la consciencia. Los miembros de la tripulación con un mediescáner, Habilidades relevantes como Primeros auxilios o Biología, o los científicos y androides que superen una <strong>Tirada de Intelecto</strong> pueden determinar tu estado.
          </div>    
        </div>
      </div>
      <div class="macro_prompt">
        Selecciona el tipo de tirada:
      </div>
    `,
    buttons: [
      {
        label: `Advantage`,
        action: `action_advantage`,
        callback: () => game.mosh.initRollTable(game.settings.get('mosh','table0eDeath'),`1d10 [+]`,`high`,false,false,null,null),
        icon: `fas fa-angle-double-up`
      },
      {
        label: `Normal`,
        action: `action_normal`,
        callback: () => game.mosh.initRollTable(game.settings.get('mosh','table0eDeath'),`1d10`,`high`,false,false,null,null),
        icon: `fas fa-minus`
      },
      {
        label: `Disadvantage`,
        action: `action_disadvantage`,
        callback: () => game.mosh.initRollTable(game.settings.get('mosh','table0eDeath'),`1d10 [-]`,`high`,false,false,null,null),
        icon: `fas fa-angle-double-down`
      }
    ]
  }).render({force: true});
}

